  json: {
    success: true,
    handoff_reason: parsed.handoff_reason || 'other',
    manager_summary: parsed.manager_summary || '',
    client_message: parsed.client_message || '',
    priority: parsed.priority || 'normal',
    next_action_recommendation: parsed.next_action_recommendation || '',
